SELECT ?item ?itemLabel ?qid WHERE {
  VALUES ?qid { 
    wd:Q1125 wd:Q17167 wd:Q1541 wd:Q10261 wd:Q1394 wd:Q170154 wd:Q7063 
    wd:Q1394963 wd:Q1235 wd:Q82955 wd:Q5891 wd:Q483353 wd:Q159810 
    wd:Q2251120 wd:Q2291991 wd:Q2033855
  }
  BIND(?qid as ?item)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}

SELECT ?work ?workLabel ?author ?authorLabel ?lcsh ?fast WHERE {
  ?work wdt:P921 wd:Q17167 .
  ?work wdt:P31/wdt:P279* wd:Q571 .
  OPTIONAL { ?work wdt:P50 ?author }
  OPTIONAL { ?work wdt:P244 ?lcsh }
  OPTIONAL { ?work wdt:P2163 ?fast }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
} LIMIT 20

SELECT ?work ?workLabel ?lcsh ?fast ?oclc WHERE {
  VALUES ?topic { wd:Q1541 wd:Q5891 wd:Q180072 wd:Q84160 wd:Q17167 }
  ?work wdt:P921 ?topic .
  ?work wdt:P31/wdt:P279* wd:Q571 .
  OPTIONAL { ?work wdt:P244 ?lcsh }
  OPTIONAL { ?work wdt:P2163 ?fast }
  OPTIONAL { ?work wdt:P243 ?oclc }
  FILTER(BOUND(?lcsh) || BOUND(?fast) || BOUND(?oclc))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
} LIMIT 15

SELECT DISTINCT ?work ?workLabel ?author ?authorLabel ?lcsh WHERE {
  VALUES ?cicero { wd:Q1541 }
  ?work wdt:P921 ?cicero .
  ?work wdt:P31/wdt:P279* wd:Q571 .
  OPTIONAL { ?work wdt:P50 ?author }
  OPTIONAL { ?work wdt:P244 ?lcsh }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
} LIMIT 10
